(function(){'use strict';function renderNavAuth(){document.querySelectorAll('.nav__auth').forEach(function(el){while(el.firstChild)el.removeChild(el.firstChild);});if(window.EFI&&typeof window.EFI.highlightActiveNavLinks==='function'){window.EFI.highlightActiveNavLinks();}}
document.addEventListener('DOMContentLoaded',renderNavAuth);})();